<?php

declare(strict_types=1);

namespace EzPhp\AsyncApi\Attributes;

use Attribute;

/**
 * Attribute Message
 *
 * Documents the annotated class as a message: its public properties are the
 * payload (schema generated by ez-php/json-schema), `$action` says whether
 * the application sends it (broadcasts, outgoing webhooks) or receives it
 * (incoming WebSocket messages, incoming webhooks).
 *
 *   #[Message('order.shipped', summary: 'An order left the warehouse')]
 *
 * @package EzPhp\AsyncApi\Attributes
 */
#[Attribute(Attribute::TARGET_CLASS)]
final readonly class Message
{
    public const string SEND = 'send';

    public const string RECEIVE = 'receive';

    /**
     * @param string      $name        Message name as it appears on the wire (e.g. the broadcast event name).
     * @param string      $action      "send" (the application publishes it) or "receive" (the application consumes it).
     * @param string|null $summary     Short summary.
     * @param string|null $description Longer description.
     */
    public function __construct(
        public string $name,
        public string $action = self::SEND,
        public ?string $summary = null,
        public ?string $description = null,
    ) {
    }
}
